// El Code node corre JavaScript. En el modo «Run Once for All Items»
// recibe todos los ítems juntos y devuelve una lista nueva de ítems.

// Acá llega 1 ítem: el que armó «Datos de ejemplo».
const datos = $input.first().json;
const cupo = datos.cupo_por_equipo; // 4 personas por equipo

// Por cada equipo de la lista devolvemos un ítem nuevo: entra 1 ítem y salen 3.
return datos.equipos.map((equipo) => {
  const lugaresLibres = cupo - equipo.integrantes;

  // Cada ítem de n8n es un objeto con la clave «json» (y «binary» si lleva archivos).
  return {
    json: {
      evento: datos.evento,
      fecha: datos.fecha,
      equipo: equipo.nombre,
      integrantes: equipo.integrantes,
      lugares_libres: lugaresLibres,
      // join arma un texto con la lista: «n8n, IA, Supabase»
      tecnologias: equipo.tecnologias.join(', '),
      usa_ia: equipo.tecnologias.includes('IA'),
    },
  };
});
